#!/bin/bash
# TriLepton production (PLAN_ConvSF step 2; 2026-11-27): all Skim_TriLep data and MC (except stage-out tests), e mu mu and mu mu mu.
# SR trees (PLAN_Signal step A, 2026-11-28): SRTree, RunSyst, BTagEffHists with the current (approximate) b-tag efficiencies (flag PreBTagEff). Output /pnfs/.../SKNanoOutput/TriLepton/Run1E2Mu_Run3Mu_SRTree_RunSyst_BTagEffHists_PreBTagEff/2024/. SR data blinded (only the nonprompt sideband is written).
cd /d0/scratch/choij/SKNanoAnalyzer && source setup.sh >/dev/null 2>&1
export SKNANO_SKIM_METADATA_DIR=/d0/scratch/choij/SKNanoAnalyzer/HcToWA_Analyzers/data/Skim
export X509_CERT_DIR=/cvmfs/grid.cern.ch/etc/grid-security/certificates
echo "proxy hours left: $(( $(voms-proxy-info -timeleft) / 3600 ))"
cd /d0/scratch/choij/hcto_prod
SKNano.py -a TriLepton -i Skim_TriLep_MuonEG,Skim_TriLep_Muon0,Skim_TriLep_Muon1 -n -100 -e 2024 --userflags Run1E2Mu,Run3Mu,SRTree,RunSyst,BTagEffHists,PreBTagEff > srtree_pre_data.log 2>&1; echo DATA_RC=$?
